import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.D9E58p8B.js";const h=JSON.parse('{"title":"Diagnostic","description":"","frontmatter":{"title":"Diagnostic"},"headers":[],"relativePath":"reference/diagnostic.md","filePath":"reference/diagnostic.md"}'),n={name:"reference/diagnostic.md"};function s(i,e,r,c,l,u){return a(),d("div",null,[...e[0]||(e[0]=[o(`<h1 id="diagnostic-l-etat-de-la-machine-et-le-plafond" tabindex="-1">Diagnostic : l&#39;état de la machine et le plafond <a class="header-anchor" href="#diagnostic-l-etat-de-la-machine-et-le-plafond" aria-label="Permalink to &quot;Diagnostic : l&#39;état de la machine et le plafond&quot;">​</a></h1><p>Deux outils en lecture seule, qui ne changent rien et n&#39;ouvrent aucune session. Ils ne sont pas soumis au plafond.</p><table tabindex="0"><thead><tr><th>Outil</th><th>Rôle</th></tr></thead><tbody><tr><td><a href="#daimon-doctor"><code>daimon_doctor</code></a></td><td>Diagnostic de toute la machine, organe par organe</td></tr><tr><td><a href="#main-ceiling"><code>main_ceiling</code></a></td><td>Plafond d&#39;autorisation actif des Mains</td></tr><tr><td><a href="#ping"><code>ping</code></a></td><td>Contrôle de santé (annexe)</td></tr></tbody></table><h2 id="daimon-doctor" tabindex="-1">daimon_doctor <a class="header-anchor" href="#daimon-doctor" aria-label="Permalink to &quot;daimon_doctor {#daimon-doctor}&quot;">​</a></h2><p>Rend l&#39;état de <strong>chaque</strong> organe en un seul appel. <strong>Appelez-le en premier</strong> quand quelque chose se comporte de façon étrange, et avant de conclure qu&#39;un outil est cassé.</p><p><strong>Paramètres</strong> : aucun. <strong>Niveau</strong> : lecture.</p><p><strong>Exemple d&#39;appel</strong> : <code>daimon_doctor</code> sans argument.</p><p><strong>Retour</strong> : un objet structuré. Les clés de premier niveau :</p><table tabindex="0"><thead><tr><th>Clé</th><th>Contenu</th></tr></thead><tbody><tr><td><code>ok</code></td><td>Verdict global : sondes fiables, Enregistrement de l&#39;écran et Accessibilité accordés, rien de cassé</td></tr><tr><td><code>backend</code></td><td>Nature de la sonde de permissions (<code>kind</code>), sa fiabilité (<code>trustworthy</code>) et une note</td></tr><tr><td><code>responsible_app</code></td><td>L&#39;application responsable, celle à laquelle le système rattache les permissions</td></tr><tr><td><code>permissions</code></td><td>Verdict réel de <code>screen_recording</code> et <code>accessibility</code> (<code>granted</code>, outils concernés)</td></tr><tr><td><code>exclusions</code></td><td>État du fichier d&#39;exclusions</td></tr><tr><td><code>organs</code></td><td>État de chaque organe</td></tr><tr><td><code>overlay</code></td><td>État du helper de l&#39;Overlay (voir ci-dessous)</td></tr><tr><td><code>consequences</code></td><td>Ce que chaque permission manquante fait concrètement à chaque outil</td></tr><tr><td><code>ceiling</code></td><td>Plafond actif, au format de <code>main_ceiling</code></td></tr><tr><td><code>cannot_detect</code></td><td>Ce que le diagnostic <strong>ne peut pas</strong> détecter</td></tr><tr><td><code>next</code></td><td>Prochaines étapes suggérées</td></tr></tbody></table><p><strong>La clé <code>overlay</code></strong> décrit le processus qui dessine l&#39;<a href="./overlay.html">Overlay</a>, sans jamais s&#39;y connecter :</p><table tabindex="0"><thead><tr><th>Sous-clé</th><th>Type</th><th>Sens</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>booléen</td><td>Le réglage « Présence à l&#39;écran » est activé</td></tr><tr><td><code>socket_present</code></td><td>booléen</td><td>Le fichier de socket du helper existe (il peut être périmé)</td></tr><tr><td><code>lock_held</code></td><td>booléen</td><td>Un helper tient le verrou : il est vivant</td></tr><tr><td><code>listening</code></td><td>booléen</td><td><code>socket_present</code> et <code>lock_held</code> ensemble : le helper vit et écoute</td></tr><tr><td><code>last_log_line</code></td><td>chaîne ou <code>null</code></td><td>Dernière ligne de <code>overlay.log</code>, tronquée à 200 caractères ; <code>null</code> si le journal est absent ou illisible</td></tr></tbody></table><p>Exemple d&#39;un helper arrêté proprement :</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;enabled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;socket_present&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;listening&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;lock_held&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;last_log_line&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-10-16T07:50:27Z overlay: exit reason=idle&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>Cette clé n&#39;influe ni sur <code>ok</code>, ni sur <code>next</code>, ni sur <code>consequences</code>.</p><p><strong>Pièges</strong></p><ul><li>Les verdicts sont sondés dans le processus courant, par des API qui ne demandent jamais d&#39;autorisation : l&#39;exécuter ne peut pas faire apparaître de boîte de dialogue.</li><li>Lisez <code>consequences</code> : sans Accessibilité, <code>main_type</code>, <code>main_key</code>, <code>main_hover</code> et <code>main_navigate</code> renvoient <code>status: &quot;done&quot;</code> comme des non-opérations silencieuses, et <code>main_click</code>, <code>main_press</code>, <code>main_drag</code> attendent 30 secondes une boîte de confirmation.</li><li>Lisez aussi <code>cannot_detect</code> : une absence de problème rapportée n&#39;est pas une preuve pour ce qui y est listé.</li></ul><h2 id="main-ceiling" tabindex="-1">main_ceiling <a class="header-anchor" href="#main-ceiling" aria-label="Permalink to &quot;main_ceiling {#main-ceiling}&quot;">​</a></h2><p>Instantané en lecture seule du plafond d&#39;autorisation actif des Mains : le niveau courant, l&#39;activité du niveau L4, le niveau nominal de chaque outil d&#39;action et ceux qui sont actuellement refusés parce qu&#39;au-dessus du plafond. C&#39;est l&#39;outil à appeler avant de piloter, pour annoncer d&#39;emblée ce que vous ne pourrez pas faire plutôt que d&#39;être refusé en cours de route.</p><p><strong>Paramètres</strong> : aucun. <strong>Niveau</strong> : lecture.</p><p><strong>Exemple d&#39;appel</strong> : <code>main_ceiling</code> sans argument.</p><p><strong>Retour</strong></p><table tabindex="0"><thead><tr><th>Clé</th><th>Type</th><th>Contenu</th></tr></thead><tbody><tr><td><code>ceiling</code></td><td>chaîne</td><td>Plafond actif : <code>READ</code>, <code>NONDESTRUCTIVE</code>, <code>INPUT</code>, <code>VALIDATION</code> ou <code>AUTONOMOUS</code></td></tr><tr><td><code>l4_active</code></td><td>booléen</td><td>Vrai quand le plafond est <code>AUTONOMOUS</code> (L4)</td></tr><tr><td><code>levels</code></td><td>objet</td><td>Nom de chaque outil d&#39;action vers son niveau nominal</td></tr><tr><td><code>gated_above</code></td><td>liste de chaînes</td><td>Outils refusés au plafond actuel, triés par ordre alphabétique</td></tr></tbody></table><p>Correspondance avec la convention L0 à L4 : <code>READ</code> = L0, <code>NONDESTRUCTIVE</code> = L1, <code>INPUT</code> = L2, <code>VALIDATION</code> = L3, <code>AUTONOMOUS</code> = L4. Les niveaux des outils sont détaillés sur la page <a href="./mains.html#niveaux">Mains</a>.</p><p><strong>Pièges</strong></p><ul><li>Un plafond qui dépasse le niveau d&#39;un outil l&#39;autorise, mais la cible peut quand même relever le niveau effectif : l&#39;absence de l&#39;outil dans <code>gated_above</code> ne garantit pas que chaque appel passera.</li><li>Une configuration malformée ou un journal absent se dégradent vers des valeurs de sécurité, sans erreur : le rapport est toujours rendu.</li><li>Le plafond est un réglage humain : aucun outil ne permet à l&#39;IA de le relever.</li></ul><h2 id="ping" tabindex="-1">ping <a class="header-anchor" href="#ping" aria-label="Permalink to &quot;ping {#ping}&quot;">​</a></h2><p>Contrôle de santé : renvoie toujours la chaîne littérale <code>pong</code>. Aucun paramètre.</p>`,27)])])}const g=t(n,[["render",s]]);export{h as __pageData,g as default};
